import { test, expect } from '@playwright/test';

test.describe('Unread vs Read Notification Visibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should visually distinguish unread notifications from read ones', async ({ page }) => {
    // Verify unread notification is visible and styled differently
    const unreadNotification = page.getByRole('alert');
    await expect(unreadNotification).toBeVisible();
    await expect(unreadNotification).toHaveClass(/unread/);

    // Verify read notification is not visible
    const readNotification = page.getByRole('alert', { name: /read/i });
    await expect(readNotification).not.toBeVisible();

    // Verify unread notification has a distinct color
    const unreadNotificationColor = page.getByRole('alert').evaluate((el) => getComputedStyle(el).backgroundColor);
    await expect(unreadNotificationColor).toBe('rgb(255, 255, 0)');

    // Verify read notification has a different color
    const readNotificationColor = page.getByRole('alert', { name: /read/i }).evaluate((el) => getComputedStyle(el).backgroundColor);
    await expect(readNotificationColor).toBe('rgb(0, 0, 0)');

    // Verify unread notification has a distinct border
    const unreadNotificationBorder = page.getByRole('alert').evaluate((el) => getComputedStyle(el).borderStyle);
    await expect(unreadNotificationBorder).toBe('solid');

    // Verify read notification has no border
    const readNotificationBorder = page.getByRole('alert', { name: /read/i }).evaluate((el) => getComputedStyle(el).borderStyle);
    await expect(readNotificationBorder).toBe('none');

    // Verify unread notification has a distinct icon
    const unreadNotificationIcon = page.getByRole('alert').evaluate((el) => getComputedStyle(el).backgroundImage);
    await expect(unreadNotificationIcon).toContain('url(/icons/unread.svg)');

    // Verify read notification has a different icon
    const readNotificationIcon = page.getByRole('alert', { name: /read/i }).evaluate((el) => getComputedStyle(el).backgroundImage);
    await expect(readNotificationIcon).toContain('url(/icons/read.svg)');

    // Verify unread notification has a distinct font style
    const unreadNotificationFont = page.getByRole('alert').evaluate((el) => getComputedStyle(el).fontWeight);
    await expect(unreadNotificationFont).toBe('bold');

    // Verify read notification has a normal font style
    const readNotificationFont = page.getByRole('alert', { name: /read/i }).evaluate((el) => getComputedStyle(el).fontWeight);
    await expect(readNotificationFont).toBe('normal');

    // Verify unread notification has a distinct text color
    const unreadNotificationTextColor = page.getByRole('alert').evaluate((el) => getComputedStyle(el).color);
    await expect(unreadNotificationTextColor).toBe('rgb(255, 255, 0)');

    // Verify read notification has a different text color
    const readNotificationTextColor = page.getByRole('alert', { name: /read/i }).evaluate((el) => getComputedStyle(el).color);
    await expect(readNotificationTextColor).toBe('rgb(0, 0, 0)');
  });

  test('should update notification status and style when toggled', async ({ page }) => {
    // Verify initial state: unread notification visible with distinct style
    const unreadNotification = page.getByRole('alert');
    await expect(unreadNotification).toBeVisible();
    await expect(unreadNotification).toHaveClass(/unread/);

    // Verify initial read notification is not visible
    const readNotification = page.getByRole('alert', { name: /read/i });
    await expect(readNotification).not.toBeVisible();

    // Toggle notification to read
    const toggleButton = page.getByRole('button', { name: /mark as read/i });
    await toggleButton.click();

    // Verify read notification becomes visible
    await expect(readNotification).toBeVisible();

    // Verify unread notification is no longer visible
    await expect(unreadNotification).not.toBeVisible();

    // Verify read notification has distinct style
    const readNotificationColor = page.getByRole('alert', { name: /read/i }).evaluate((el) => getComputedStyle(el).backgroundColor);
    await expect(readNotificationColor).toBe('rgb(0, 0, 0)');

    // Verify read notification has a distinct border
    const readNotificationBorder = page.getByRole('alert', { name: /read/i }).evaluate((el) => getComputedStyle(el).borderStyle);
    await expect(readNotificationBorder).toBe('solid');

    // Verify read notification has a distinct icon
    const readNotificationIcon = page.getByRole('alert', { name: /read/i }).evaluate((el) => getComputedStyle(el).backgroundImage);
    await expect(readNotificationIcon).toContain('url(/icons/read.svg)');

    // Verify read notification has a distinct font style
    const readNotificationFont = page.getByRole('alert', { name: /read/i }).evaluate((el) => getComputedStyle(el).fontWeight);
    await expect(readNotificationFont).toBe('normal');

    // Verify read notification has a distinct text color
    const readNotificationTextColor = page.getByRole('alert', { name: /read/i }).evaluate((el) => getComputedStyle(el).color);
    await expect(readNotificationTextColor).toBe('rgb(0, 0, 0)');

    // Verify unread notification is no longer visible
    const unreadNotification = page.getByRole('alert');
    await expect(unreadNotification).not.toBeVisible();
  });
});
